namespace sv_7b731ef7428c48fabcbbd4dfecd9920f.Services;

/// <summary>
/// Scoped service (per circuit) that tracks low-stock alert counts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="CurrentAlertCount"/> changes.
    /// Subscribers must wrap StateHasChanged in InvokeAsync because
    /// this event can fire from a timer thread.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Updates the cached alert count and notifies all subscribers.
    /// Called by whichever component owns the polling loop.
    /// </summary>
    public void UpdateAlertCount(int newCount)
    {
        CurrentAlertCount = newCount;
        OnChange?.Invoke();
    }
}

