@page "/dashboard"
@using sv_7b731ef7428c48fabcbbd4dfecd9920f.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard — @(Warehouse?.WarehouseName ?? "Loading…")</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4">
                    <AlertBadge />
                </p>
                <p class="text-muted">items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="display-6">@(Warehouse?.WarehouseName ?? "—")</p>
                <p class="text-muted">@(Warehouse?.WarehouseId ?? "")</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">@(_isPolling ? "Active" : "Stopped")</p>
                <p class="text-muted">every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _isPolling;

    protected override async Task OnInitializedAsync()
    {
        await PollOnceAsync();
        StartPolling();
    }

    protected override async Task OnParametersSetAsync()
    {
        // Warehouse changed (user picked a new one) — refresh immediately.
        await PollOnceAsync();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();

                // We're on a timer thread — must marshal to the Blazor sync context.
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose.
        }
    }

    private async Task PollOnceAsync()
    {
        var warehouseId = Warehouse?.WarehouseId ?? "WH-001";
        var count = await AlertService.GetLowStockCountAsync(warehouseId);

        // This fires OnChange, which notifies every subscriber (sidebar badge, etc.)
        AlertService.UpdateAlertCount(count);
    }

    public void Dispose()
    {
        _isPolling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

